insert into public.grammar_topics (slug, title, summary, tip_tr, example, difficulty) values
  ('be-am-is-are', 'To be: am / is / are', 'Use am with I, is with he/she/it, are with you/we/they for identity, feelings, and location.', 'I am · he/she/it is · you/we/they are', 'I am a student. She is tired. They are at home.', 1),
  ('subject-pronouns', 'Subject pronouns', 'I, you, he, she, it, we, they replace the subject of a sentence.', 'I / you / he / she / it / we / they', 'Ali is here. He is here.', 1),
  ('possessive-adjectives', 'Possessive adjectives', 'my, your, his, her, its, our, their come before a noun to show ownership.', 'my book · her name · their car', 'This is my bag. That is her phone.', 1),
  ('articles-a-an', 'Articles: a / an', 'a/an = one (not specific). Use an before a vowel sound.', 'a book · an apple · an hour (sesli harf sesi)', 'I need a pen and an eraser.', 1),
  ('articles-a-an-the', 'Articles: a / an / the', 'a/an = one (not specific). the = specific / known to speaker and listener.', 'a/an = belirsiz · the = belirli', 'I bought an apple and the apple was sweet.', 1),
  ('plurals', 'Plural nouns', 'Most nouns add -s/-es. Watch irregular plurals (child → children, mouse → mice).', 'book → books · box → boxes · child → children', 'Two books, three boxes, five children.', 1),
  ('this-that-these-those', 'Demonstratives: this / that / these / those', 'this/these = near; that/those = far. this/that singular; these/those plural.', 'this/these = yakın · that/those = uzak', 'This book is mine. Those cars are expensive.', 1),
  ('there-is-are', 'There is / there are', 'Use there is + singular and there are + plural to say something exists.', 'There is a… · There are two…', 'There is a café nearby. There are many students.', 1),
  ('have-has', 'Have / has', 'have with I/you/we/they; has with he/she/it for possession.', 'I have · she has', 'I have a bike. She has two cats.', 1),
  ('present-simple', 'Present Simple', 'Use Present Simple for habits, routines, and facts. Add -s/-es with he/she/it.', 'Alışkanlık ve gerçekler: I work / she works.', 'She goes to school every day.', 1),
  ('present-simple-neg-q', 'Present Simple: negatives & questions', 'Negatives and questions use do/does + base verb.', 'don''t/doesn''t + V1 · Do/Does + özne + V1?', 'She doesn''t like tea. Do you live here?', 1),
  ('present-continuous', 'Present Continuous', 'Use am/is/are + verb-ing for actions happening now or around now.', 'Şu an: am/is/are + V-ing', 'They are playing football right now.', 1),
  ('can-cant', 'Can / can''t (ability & permission)', 'can + base verb for ability or permission; can''t for inability or refusal.', 'can + V1 · can''t = cannot', 'I can swim. Can I open the window?', 1),
  ('imperatives', 'Imperatives', 'Use the base verb to give orders, requests, and instructions. Don''t + verb for negatives.', 'Open the door. · Don''t run.', 'Sit down. Don''t touch that.', 1),
  ('in-on-at', 'Prepositions: in / on / at (place)', 'in = enclosed space; on = surface; at = exact point.', 'in = içinde · on = üzerinde · at = noktada', 'She is at school. The book is on the table. We live in Ankara.', 1),
  ('prepositions-time', 'Prepositions of time', 'in + months/years/parts of day; on + days/dates; at + clock times / night.', 'in July · on Monday · at 7 o''clock', 'I was born in 2005. See you on Friday at 6.', 1),
  ('wh-questions', 'Wh- questions', 'who, what, where, when, why, how ask for specific information.', 'Who / What / Where / When / Why / How', 'Where do you live? Why are you late?', 1),
  ('adjectives-basic', 'Adjectives (basic)', 'Adjectives describe nouns and usually come before the noun or after be.', 'a big house · She is happy.', 'It is a cold day. The film was boring.', 1),
  ('adverbs-frequency', 'Adverbs of frequency', 'always, usually, often, sometimes, rarely, never usually go before the main verb (after be).', 'always → never · be''den sonra, diğer fiilden önce', 'She always arrives early. He is never late.', 1),
  ('object-pronouns', 'Object pronouns', 'me, you, him, her, it, us, them replace the object of a verb or preposition.', 'me / him / her / us / them', 'Call me. I saw them yesterday.', 1),
  ('possessive-s', 'Possessive ''s', 'Add ''s to a person/animal to show ownership. Plural ending in s takes only ''.', 'Ali''s bag · the students'' books', 'This is Sara''s phone. The boys'' room is tidy.', 1),
  ('past-simple', 'Past Simple', 'Use Past Simple for finished actions in the past. Regular verbs take -ed; many are irregular.', 'Bitmiş geçmiş: V2 (worked / went)', 'I watched a movie last night.', 2),
  ('past-simple-irregular', 'Past Simple: irregular verbs', 'Common irregulars: go→went, see→saw, have→had, make→made, take→took.', 'go–went · see–saw · take–took · make–made', 'She went home. He took the bus.', 2),
  ('past-continuous', 'Past Continuous', 'was/were + V-ing for an action in progress at a past moment (often interrupted).', 'was/were + V-ing', 'I was cooking when she called.', 2),
  ('going-to', 'Future: be going to', 'am/is/are + going to + verb for plans and predictions from present evidence.', 'be + going to + V1', 'I''m going to study tonight. Look at those clouds — it''s going to rain.', 2),
  ('will-future', 'Future: will', 'will + base verb for instant decisions, offers, promises, and predictions.', 'will + V1 · won''t = will not', 'I''ll help you. It will be sunny tomorrow.', 2),
  ('present-continuous-future', 'Present Continuous for future', 'am/is/are + V-ing for fixed personal arrangements in the near future.', 'Yarınki randevu: I''m meeting Ali at 5.', 'We''re flying to Izmir on Friday.', 2),
  ('present-perfect', 'Present Perfect', 'have/has + past participle for life experience and actions linked to now (for/since).', 'have/has + V3 · for / since', 'She has lived in London since 2010.', 2),
  ('present-perfect-vs-past', 'Present Perfect vs Past Simple', 'Present Perfect = unfinished time / result now. Past Simple = finished time (yesterday, in 2019).', 'ever/never/just → Perfect · yesterday/last… → Past', 'I have seen that film. I saw it last week.', 2),
  ('comparatives', 'Comparatives', 'Compare two things: adj + -er + than, or more + adj + than for longer adjectives.', 'taller than · more interesting than · better/worse', 'This bag is cheaper than that one.', 2),
  ('superlatives', 'Superlatives', 'the + adj-est or the most + adj to say something is number one in a group.', 'the tallest · the most expensive · the best', 'She is the fastest runner in the class.', 2),
  ('countable-uncountable', 'Countable & uncountable nouns', 'Countable have singular/plural (a book / books). Uncountable have no plural (water, advice, information).', 'a/an/many + sayıla bilir · much/some + sayılamaz', 'I need some water and two apples.', 2),
  ('some-any-much-many', 'Some / any / much / many', 'some (positive), any (questions/negatives); many + countable, much + uncountable.', 'some (+) · any (?/–) · many books · much time', 'Do you have any sugar? I don''t have much time.', 2),
  ('modals-obligation', 'Must / have to / should', 'must/have to = obligation; should = advice; mustn''t = prohibition; don''t have to = no need.', 'must/have to = zorunluluk · should = tavsiye', 'You should sleep more. You mustn''t smoke here.', 2),
  ('could-would', 'Could / would', 'could = past ability / polite request; would like = polite want; would = hypothetical.', 'Could you…? · I''d like… · I could swim (geçmiş)', 'Could you help me? I''d like a coffee.', 2),
  ('first-conditional', 'First conditional', 'If + Present Simple, will + verb for real future possibilities.', 'If it rains, I will stay home.', 'If you study, you will pass.', 2),
  ('gerunds-infinitives', 'Gerunds & infinitives', 'Some verbs take -ing (enjoy swimming); others take to + verb (want to go).', 'enjoy + V-ing · want + to V', 'I enjoy reading. She wants to travel.', 2),
  ('relative-who-which', 'Relative pronouns: who / which / that', 'who = people; which = things; that = people or things in defining clauses.', 'who = kişi · which = şey · that = ikisi', 'The man who called is my teacher.', 2),
  ('articles-the', 'Articles: the (specific use)', 'the for unique things, second mention, superlatives, and known shared context.', 'the sun · the first one · the same café', 'The moon is bright tonight.', 2),
  ('adverbs-manner', 'Adverbs of manner', 'Many adverbs add -ly to adjectives (quick → quickly) and say how something happens.', 'slow → slowly · careful → carefully · fast/hard (aynı)', 'She speaks English clearly.', 2),
  ('used-to', 'Used to', 'used to + verb for past habits or states that are no longer true.', 'used to + V1 (eskiden … yapardım)', 'I used to play tennis every week.', 2),
  ('present-perfect-continuous', 'Present Perfect Continuous', 'have/has been + V-ing for actions that started in the past and continue, or just stopped with a visible result.', 'have/has been + V-ing', 'I have been waiting for an hour.', 3),
  ('past-perfect', 'Past Perfect', 'had + V3 for an action completed before another past action.', 'had + V3 (önce bitmiş geçmiş)', 'She had left before I arrived.', 3),
  ('past-perfect-continuous', 'Past Perfect Continuous', 'had been + V-ing for a continuous action before a past point.', 'had been + V-ing', 'He had been working all day before the meeting.', 3),
  ('future-continuous', 'Future Continuous', 'will be + V-ing for an action in progress at a future time.', 'will be + V-ing', 'This time tomorrow I will be flying to Rome.', 3),
  ('future-perfect', 'Future Perfect', 'will have + V3 for an action completed before a future deadline.', 'will have + V3', 'By Friday I will have finished the report.', 3),
  ('second-conditional', 'Second conditional', 'If + Past Simple, would + verb for unreal or unlikely present/future situations.', 'If I were rich, I would travel.', 'If I had more time, I would learn piano.', 3),
  ('third-conditional', 'Third conditional', 'If + Past Perfect, would have + V3 for unreal past (regret / different past).', 'If I had studied, I would have passed.', 'If she had left earlier, she would have caught the train.', 3),
  ('passive-voice', 'Passive voice', 'be + V3 when the focus is on the action/result, not the doer (by + agent optional).', 'be + V3 · The letter was sent.', 'English is spoken here. The cake was made by Tom.', 3),
  ('reported-speech', 'Reported speech', 'Backshift tenses when reporting past statements; change pronouns and time words.', 'am → was · will → would · today → that day', 'She said she was tired. He told me he would call.', 3),
  ('relative-clauses', 'Relative clauses', 'Defining clauses identify the noun; non-defining add extra info and use commas.', 'tanımlayan (virgülsüz) · ek bilgi (virgüllü)', 'My brother, who lives in Berlin, is a doctor.', 3),
  ('modals-deduction', 'Modals of deduction', 'must = certainty; might/may/could = possibility; can''t = impossibility (about now).', 'must be · might be · can''t be', 'He must be at work. That can''t be true.', 3),
  ('wish-if-only', 'Wish / if only', 'wish + Past Simple (present regret); wish + Past Perfect (past regret); wish + would (annoyance).', 'I wish I knew · I wish I had gone', 'I wish I spoke French. If only I had listened.', 3),
  ('so-such', 'So / such', 'so + adjective/adverb; such + (a/an) + adjective + noun for emphasis.', 'so tired · such a long day', 'It was so cold. It was such a cold night.', 3),
  ('enough-too', 'Enough / too', 'too = more than wanted; enough = as much as needed (adj + enough / enough + noun).', 'too heavy · tall enough · enough money', 'This bag is too heavy. I''m not tall enough.', 3),
  ('both-either-neither', 'Both / either / neither', 'both = the two; either = one or the other; neither = not one and not the other.', 'both of them · either option · neither works', 'Both answers are correct. Neither team scored.', 3),
  ('quantifiers', 'Quantifiers (few / little / plenty)', 'a few/few + countable; a little/little + uncountable; plenty of = more than enough.', 'a few friends · little time · plenty of food', 'I have a few ideas but little money.', 3),
  ('linking-words', 'Linking words', 'although, however, therefore, because, so, while connect ideas logically.', 'although / however / therefore / because', 'Although it rained, we went out.', 3),
  ('phrasal-verbs', 'Phrasal verbs', 'Verb + particle with a special meaning (look up, give up, turn on). Some are separable.', 'look up · give up · turn on (ayrılabilir olanlar)', 'Please turn the lights off. She gave up smoking.', 3),
  ('mixed-conditionals', 'Mixed conditionals', 'Mix past and present unreal forms: past cause → present result, or present condition → past result.', 'If I had…, I would be… (geçmiş → şimdi)', 'If I had studied medicine, I would be a doctor now.', 4),
  ('causative', 'Causative: have / get something done', 'have/get + object + V3 when someone else does the action for you.', 'have/get + nesne + V3', 'I had my hair cut. She got her car repaired.', 4),
  ('advanced-passive', 'Advanced passive', 'Passive with modals, reporting verbs (it is said that…), and get-passive.', 'It is said that… · The window got broken.', 'It is believed that the company will expand.', 4),
  ('reported-questions', 'Reported questions & commands', 'No do-support; use if/whether for yes-no; ask/tell + object + to-infinitive for commands.', 'He asked where I lived. · She told me to wait.', 'She asked if I was ready. He told us to sit down.', 4),
  ('modals-perfect', 'Modals + perfect infinitive', 'must/might/should/could + have + V3 for past deduction, advice, and possibility.', 'must have · should have · could have', 'You should have called. He must have forgotten.', 4),
  ('future-in-the-past', 'Future in the past', 'was/were going to, would, was about to for planned or expected future from a past viewpoint.', 'was going to · would · was about to', 'I was going to call, but my phone died.', 4),
  ('participle-clauses', 'Participle clauses', 'Use -ing / -ed clauses to shorten relative or adverbial clauses.', 'Walking home, I met Ali. · Built in 1900,…', 'Feeling tired, she went to bed early.', 4),
  ('relative-advanced', 'Advanced relative clauses', 'whose, where, when, why; preposition + which/whom; reduced relatives.', 'whose · of which · the man I met', 'The woman whose car was stolen called the police.', 4),
  ('inversion-conditionals', 'Inversion in conditionals', 'Formal: Had I known… / Were I you… / Should you need… instead of if-clauses.', 'Had I known… = If I had known…', 'Had I known, I would have helped.', 4),
  ('cleft-sentences', 'Cleft sentences', 'It is/was … that/who and What … is/was to emphasize one part of a sentence.', 'It was Ali who called. · What I need is rest.', 'It was yesterday that we met.', 4),
  ('discourse-markers', 'Discourse markers', 'anyway, actually, on the other hand, in contrast, furthermore structure spoken and written argument.', 'however · furthermore · on the other hand', 'On the other hand, costs may rise.', 4),
  ('noun-phrases', 'Complex noun phrases', 'Stack determiners, adjectives, and of-phrases to pack information into one noun group.', 'the sudden rise in prices · a well-known expert', 'The rapid growth of online shopping surprised analysts.', 4),
  ('inversion', 'Inversion (negative adverbials)', 'After never, rarely, not only, under no circumstances… invert auxiliary + subject for emphasis.', 'Never have I… · Not only did she…', 'Never have I seen such chaos. Rarely does he complain.', 5),
  ('subjunctive', 'Subjunctive', 'Base verb after suggest/recommend/insist that… and in formal phrases (God save…, be that as it may).', 'I suggest that he go… (bare infinitive)', 'They recommended that she apply early.', 5),
  ('nominalisation', 'Nominalisation', 'Turn verbs/adjectives into nouns for a more academic, formal style.', 'decide → decision · develop → development', 'Their decision to expand led to rapid growth.', 5),
  ('ellipsis-substitution', 'Ellipsis & substitution', 'Omit repeated words or replace them with so/do/one to avoid repetition.', 'I think so. · so do I · a red one', 'She can swim and so can I. I''ll take the blue one.', 5),
  ('emphatic-structures', 'Emphatic structures', 'do/does/did for emphasis; fronting; rhetorical inversion for style.', 'I do understand. · Never again will I…', 'I did tell you. What a mess this is!', 5),
  ('advanced-modals', 'Advanced modality & hedging', 'hedges (seem, appear, tend to), probability scales, and formal obligation (be to / be supposed to).', 'seem to · be supposed to · be to', 'Prices appear to be rising. You are to report by noon.', 5),
  ('hypothesis-speculation', 'Hypothesis & speculation', 'suppose, imagine, what if, as if/as though, and speculative modals for nuanced meaning.', 'as if · suppose · might well', 'He talks as if he knew everything. She might well refuse.', 5),
  ('register-formality', 'Register & formality', 'Choose formal vs informal grammar and vocabulary for academic, professional, or casual contexts.', 'Could you…? (resmi) · Can you…? (günlük)', 'I would appreciate your assistance. / Can you help?', 5)
